import{_ as a,o as t,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"Web 音视频与实时通信全景","description":"","frontmatter":{"title":"Web 音视频与实时通信全景","outline":[2,3]},"headers":[],"relativePath":"frontend/topics/media-realtime/index.md","filePath":"frontend/topics/media-realtime/index.md","lastUpdated":1785589115000}'),i={name:"frontend/topics/media-realtime/index.md"};function d(s,e,l,o,c,p){return t(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="web-音视频与实时通信全景" tabindex="-1">Web 音视频与实时通信全景 <a class="header-anchor" href="#web-音视频与实时通信全景" aria-label="Permalink to &quot;Web 音视频与实时通信全景&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Web 音视频横跨压缩编码、容器、时间轴、网络分发、设备采集、音频图、实时传输和浏览器权限。能播放一个 MP4 不等于理解直播，能取得摄像头也不等于完成会议；每个场景都需要独立的数据模型和生命周期。</p><p>本分组以浏览器端为中心，说明媒体怎样被描述、播放、采集、处理和实时传输。服务端只介绍前端必须协作的协议和边界，不展开媒体服务器内部实现。</p><h2 id="_1-能力地图" tabindex="-1">1. 能力地图 <a class="header-anchor" href="#_1-能力地图" aria-label="Permalink to &quot;1. 能力地图&quot;">​</a></h2><h3 id="_1-1-播放与流式缓冲" tabindex="-1">1.1 播放与流式缓冲 <a class="header-anchor" href="#_1-1-播放与流式缓冲" aria-label="Permalink to &quot;1.1 播放与流式缓冲&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>核心问题</th></tr></thead><tbody><tr><td><a href="/frontend/topics/media-realtime/containers-codecs-timeline">媒体格式、编解码与时间轴</a></td><td>Container、Codec、Track、PTS/DTS、Keyframe 与 MIME 能力判断</td></tr><tr><td><a href="/frontend/topics/media-realtime/media-element">HTMLMediaElement 与媒体播放</a></td><td><code>video</code> / <code>audio</code> 的加载、播放、缓冲、Seeking、字幕和错误状态</td></tr><tr><td><a href="/frontend/topics/media-realtime/media-source">MSE 与流式媒体播放</a></td><td>应用怎样追加媒体 Segment、管理 Buffer 和自适应切换</td></tr></tbody></table><h3 id="_1-2-采集、录制与处理" tabindex="-1">1.2 采集、录制与处理 <a class="header-anchor" href="#_1-2-采集、录制与处理" aria-label="Permalink to &quot;1.2 采集、录制与处理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>核心问题</th></tr></thead><tbody><tr><td><a href="/frontend/topics/media-realtime/media-capture">摄像头、麦克风与屏幕采集</a></td><td>权限、Constraint、Track、设备切换与生命周期</td></tr><tr><td><a href="/frontend/topics/media-realtime/media-recorder">MediaRecorder 与媒体录制</a></td><td>浏览器编码、Chunk、暂停恢复、错误与上传边界</td></tr><tr><td><a href="/frontend/topics/media-realtime/web-audio">Web Audio 与音频处理</a></td><td>AudioContext、Node Graph、时钟、分析、混音和资源释放</td></tr><tr><td><a href="/frontend/topics/media-realtime/webcodecs">WebCodecs 与帧级媒体处理</a></td><td>Encoded/Raw Frame、Decoder/Encoder、Backpressure 与容器边界</td></tr></tbody></table><h3 id="_1-3-实时互动与分发" tabindex="-1">1.3 实时互动与分发 <a class="header-anchor" href="#_1-3-实时互动与分发" aria-label="Permalink to &quot;1.3 实时互动与分发&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>核心问题</th></tr></thead><tbody><tr><td><a href="/frontend/topics/media-realtime/webrtc">WebRTC 连接、信令与 NAT 穿透</a></td><td>SDP、ICE、STUN/TURN、Offer/Answer 与连接状态机</td></tr><tr><td><a href="/frontend/topics/media-realtime/webrtc-media-data-quality">WebRTC 媒体轨道、数据通道与质量</a></td><td>Transceiver、Track、DataChannel、Stats、自适应与重连</td></tr><tr><td><a href="/frontend/topics/media-realtime/live-low-latency">直播分发与低延迟架构</a></td><td>HLS/DASH、LL-HLS、WebRTC、WebTransport 的规模与延迟取舍</td></tr></tbody></table><h2 id="_2-数据结果流" tabindex="-1">2. 数据结果流 <a class="header-anchor" href="#_2-数据结果流" aria-label="Permalink to &quot;2. 数据结果流&quot;">​</a></h2><h3 id="_2-1-点播" tabindex="-1">2.1 点播 <a class="header-anchor" href="#_2-1-点播" aria-label="Permalink to &quot;2.1 点播&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>媒体文件 / Manifest</span></span>
<span class="line"><span>  -&gt; 网络请求</span></span>
<span class="line"><span>  -&gt; Demux Container</span></span>
<span class="line"><span>  -&gt; Decode Audio/Video</span></span>
<span class="line"><span>  -&gt; Audio clock + Video presentation</span></span>
<span class="line"><span>  -&gt; HTMLMediaElement 输出</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>普通 <code>&lt;video src&gt;</code> 由浏览器管理这条链路；MSE 让应用接管 Segment 下载和缓冲，但解封装、解码和播放时钟仍由媒体管线承担。</p><h3 id="_2-2-采集与会议" tabindex="-1">2.2 采集与会议 <a class="header-anchor" href="#_2-2-采集与会议" aria-label="Permalink to &quot;2.2 采集与会议&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Camera / Microphone</span></span>
<span class="line"><span>  -&gt; MediaStreamTrack</span></span>
<span class="line"><span>  -&gt; Web Audio / Canvas / WebCodecs（可选处理）</span></span>
<span class="line"><span>  -&gt; RTCPeerConnection 编码与传输</span></span>
<span class="line"><span>  -&gt; Remote Track</span></span>
<span class="line"><span>  -&gt; HTMLMediaElement</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>信令不传媒体，它只交换 SDP、ICE Candidate 和业务会话信息。TURN 转发媒体时带宽与成本显著，不能当作偶发兜底而不监控。</p><h2 id="_3-三个时间系统" tabindex="-1">3. 三个时间系统 <a class="header-anchor" href="#_3-三个时间系统" aria-label="Permalink to &quot;3. 三个时间系统&quot;">​</a></h2><ul><li>媒体时间：Track 中的 Timestamp、Duration 与 Timescale；</li><li>播放时钟：<code>HTMLMediaElement.currentTime</code> 或 AudioContext Clock；</li><li>墙上时间：直播节目时间、服务端时间和用户看到的延迟。</li></ul><p>三者不能直接等同。Seek、倍速、暂停和缓冲都会改变播放时钟与墙上时间的关系；音视频同步需要共同时间基准和时钟漂移处理。</p><h2 id="_4-选型入口" tabindex="-1">4. 选型入口 <a class="header-anchor" href="#_4-选型入口" aria-label="Permalink to &quot;4. 选型入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品目标</th><th>前端主能力</th></tr></thead><tbody><tr><td>普通点播</td><td>HTMLMediaElement + CDN 文件或 HLS/DASH 播放器</td></tr><tr><td>可控自适应点播/直播</td><td>MSE + Manifest/Segment 调度库</td></tr><tr><td>摄像头预览和拍摄</td><td>Media Capture + MediaRecorder / WebCodecs</td></tr><tr><td>双向会议</td><td>WebRTC + 信令 + STUN/TURN + SFU 服务</td></tr><tr><td>浏览器音频工作站</td><td>Web Audio + Worker / AudioWorklet</td></tr><tr><td>帧级特效、转码、低级处理</td><td>WebCodecs，必要时配合 Wasm / WebGPU</td></tr><tr><td>大规模单向直播</td><td>HLS/DASH/LL-HLS；超低延迟互动再评估 WebRTC</td></tr></tbody></table><h2 id="_5-兼容与权限基线" tabindex="-1">5. 兼容与权限基线 <a class="header-anchor" href="#_5-兼容与权限基线" aria-label="Permalink to &quot;5. 兼容与权限基线&quot;">​</a></h2><ul><li>媒体采集要求安全上下文和用户授权；</li><li>自动播放通常要求静音、用户激活或浏览器已建立媒体参与度；</li><li>Codec、Container 和硬件加速支持取决于浏览器、系统和设备；</li><li>WebCodecs、AudioWorklet、屏幕采集和部分 Stats 字段需特性检测；</li><li>iOS、后台标签、省电模式、蓝牙切换和系统来电会改变生命周期；</li><li>真实部署必须测试 DRM、跨域、Range Request、CSP 和权限策略。</li></ul><h2 id="_6-推荐学习顺序" tabindex="-1">6. 推荐学习顺序 <a class="header-anchor" href="#_6-推荐学习顺序" aria-label="Permalink to &quot;6. 推荐学习顺序&quot;">​</a></h2><ol><li>Container、Codec、Track、Timestamp 和 Keyframe。</li><li>HTMLMediaElement 的播放状态和错误处理。</li><li>根据业务进入 MSE，或进入采集、录制和 Web Audio。</li><li>实时互动再学习 SDP、ICE、Track、DataChannel 和 Stats。</li><li>WebCodecs 与低延迟架构放在明确需要帧级控制或更低延迟时学习。</li></ol><h2 id="_7-掌握标准" tabindex="-1">7. 掌握标准 <a class="header-anchor" href="#_7-掌握标准" aria-label="Permalink to &quot;7. 掌握标准&quot;">​</a></h2><ul><li>能从 Codec String 和浏览器能力判断为什么“同为 MP4”仍可能无法播放。</li><li>能解释 <code>play()</code>、Buffer、Seek、Ended 和 Error 的异步状态。</li><li>能安全申请、切换和停止设备 Track，并处理权限拒绝。</li><li>能完成 WebRTC Offer/Answer、ICE、TURN 回退和连接诊断。</li><li>能从 <code>getStats()</code> 区分带宽、丢包、抖动、解码和渲染问题。</li><li>能按观众规模、目标延迟和成本选择直播分发方案。</li></ul><h2 id="_8-参考资料" tabindex="-1">8. 参考资料 <a class="header-anchor" href="#_8-参考资料" aria-label="Permalink to &quot;8. 参考资料&quot;">​</a></h2><ul><li><a href="https://html.spec.whatwg.org/multipage/media.html" target="_blank" rel="noreferrer">WHATWG HTML：Media elements</a></li><li><a href="https://www.w3.org/TR/mediacapture-streams/" target="_blank" rel="noreferrer">Media Capture and Streams</a></li><li><a href="https://www.w3.org/TR/webrtc/" target="_blank" rel="noreferrer">WebRTC 1.0</a></li><li><a href="https://www.w3.org/TR/webcodecs/" target="_blank" rel="noreferrer">WebCodecs</a></li></ul>`,31)])])}const m=a(i,[["render",d]]);export{b as __pageData,m as default};
